(() => {
  const photos = {"biankatemperine":"data:image/jpeg;base64,","learteatelie":"data:image/jpeg;base64,","ateliedelapassion":"data:image/jpeg;base64,","dclickentretenimento":"data:image/jpeg;base64,","hmproducoes":"data:image/jpeg;base64,","avdigital":"data:image/jpeg;base64,","ateliemayrabueno":"data:image/jpeg;base64,","antaragold":"data:image/jpeg;base64,","kdproducoes":"data:image/jpeg;base64,","ingridfreitasbeauty":"data:image/jpeg;base64,","carollcardozo":"data:image/jpeg;base64,","acfotoefilme":"data:image/jpeg;base64,","oseletricos":"data:image/jpeg;base64,","nandodocesfinos":"data:image/jpeg;base64,","doceselidelicias":"data:image/jpeg;base64,","bd360eventos":"data:image/jpeg;base64,"};
  const normalize = (value) => String(value || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/[^a-z0-9]+/gi, '').toLowerCase();
  const applyPhotos = () => {
    document.querySelectorAll('.supplier-card').forEach((card) => {
      const name = normalize(card.querySelector('h3')?.textContent);
      const source = photos[name];
      const logo = card.querySelector('.supplier-logo');
      if (!source || !logo) return;
      logo.classList.add('has-photo', 'has-supplier-logo');
      let image = logo.querySelector('.supplier-photo');
      if (!image) {
        image = document.createElement('img');
        image.className = 'supplier-photo';
        logo.prepend(image);
      }
      image.src = source;
      image.alt = card.querySelector('h3')?.textContent?.trim() || 'Logo do fornecedor';
    });
  };
  const start = () => {
    applyPhotos();
    const grid = document.querySelector('#supplierGrid');
    if (grid) new MutationObserver(applyPhotos).observe(grid, { childList: true, subtree: true });
  };
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', start);
  else start();
})();
